CREATE TABLE public.subscription_usage ("api_calls_count" integer DEFAULT 0 NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"exports_count" integer DEFAULT 0 NOT NULL,"id" uuid DEFAULT gen_random_uuid() NOT NULL,"period_end" date NOT NULL,"period_start" date NOT NULL,"skip_traces_count" integer DEFAULT 0 NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL,"user_id" uuid NOT NULL);

ALTER TABLE public.subscription_usage ADD CONSTRAINT "subscription_usage_pkey" PRIMARY KEY (id);

